def deps(seat):
    return (f"Install your own client deps first (npm registry; record version/channel in your report): D={SC}/{seat}/deps; "
            f"mkdir -p \"$D\" && cd \"$D\" && npm init -y >/dev/null && npm install --no-audit --no-fund puppeteer-core@25.16.0 playwright-core@1.65.0.\n")
def cmd(seat, run, ports, extra=''):
    return (f"node {CNT} --lane {L} --expect-driver-sha256 {DP} --live --deps {SC}/{seat}/deps --scratch {SC}/{seat}/{run} "
            f"--ports {ports} --json{extra}")
